program(1.3)
[buildInfo = dict<string, string>({})]
{
  func main<ios18>(tensor<fp16, [1, 128, 1, 1]> x) {
    tensor<fp16, [1, 128, 1, 1]> gamma = const()[name = string("gamma"), val = tensor<fp16, [1, 128, 1, 1]>(BLOBFILE(path = string("@model_path/weights.bin"), offset = uint64(64)))];
    tensor<fp16, [1, 128, 1, 1]> abs0 = abs(x = x)[name = string("abs0")];
    tensor<int32, [3]> axes = const()[name = string("axes"), val = tensor<int32, [3]>([1, 2, 3])];
    tensor<fp16, [1, 1, 1, 1]> amax = reduce_max(x = abs0, axes = axes, keep_dims = bool(true))[name = string("amax")];
    tensor<fp16, [1, 128, 1, 1]> scaled = real_div(x = x, y = amax)[name = string("scaled")];
    tensor<fp16, [1, 128, 1, 1]> sq = square(x = scaled)[name = string("sq")];
    tensor<fp16, [1, 1, 1, 1]> mean = reduce_mean(x = sq, axes = axes, keep_dims = bool(true))[name = string("mean")];
    fp16 eps = const()[name = string("eps"), val = fp16(0x1p-17)];
    tensor<fp16, [1, 1, 1, 1]> meps = add(x = mean, y = eps)[name = string("meps")];
    tensor<fp16, [1, 1, 1, 1]> rms = sqrt(x = meps)[name = string("rms")];
    tensor<fp16, [1, 1, 1, 1]> rscaled = mul(x = rms, y = amax)[name = string("rscaled")];
    tensor<fp16, [1, 128, 1, 1]> norm = real_div(x = x, y = rscaled)[name = string("norm")];
    tensor<fp16, [1, 128, 1, 1]> y = mul(x = norm, y = gamma)[name = string("y")];
  } -> (y);
}
